-- ════════ 20261015100000_sitam_v3 ════════
/* SITAM SPACE v3 — roles, auto-delegation and moderation
   ─────────────────────────────────────────────────────────────
   • New role "phd" (PhD student): applies like a student and publishes own research.
   • Professors post opportunities as themselves (person host) → they appear in Opportunities.
   • Students / PhD submit projects, startups and research → admin moderation → catalog.
     PhD research is published immediately.
   • Professor metrics refresh automatically from linked publications.
   • Applicant dashboard shows contacts (e-mail, phone) and CV.
   Note: new enum values are compared as text inside SQL functions, so the whole file
   can run in one transaction. */

alter type public.app_role add value if not exists 'phd';
alter type public.project_kind add value if not exists 'project';

/* ───────────── profiles: phone for applicant contacts ───────────── */
alter table public.profiles add column if not exists phone text check (phone is null or phone ~ '^[0-9 +()-]{6,24}$');
grant update (phone) on public.profiles to authenticated;

/* ───────────── opportunities posted by a person (professor) ───────────── */
alter table public.opportunity_hosts add column if not exists person_id uuid references public.profiles(id) on delete cascade;
alter table public.opportunity_hosts add column if not exists person_name text;
alter table public.opportunity_hosts add column if not exists person_username text;   -- research page of the professor, if any
alter table public.opportunity_hosts drop constraint if exists one_host_per_row;
alter table public.opportunity_hosts add constraint one_host_per_row check (num_nonnulls(lab_id, company_id, project_id, person_id) = 1);
drop index if exists public.opportunity_hosts_unique;
create unique index opportunity_hosts_unique on public.opportunity_hosts(opportunity_id, coalesce(lab_id, company_id, project_id, person_id));
create index if not exists opportunity_hosts_person_idx on public.opportunity_hosts(person_id);

/* ───────────── projects: student / PhD submissions with moderation ───────────── */
alter table public.projects alter column lab_id drop not null;
alter table public.projects add column if not exists owner_id uuid references public.profiles(id) on delete cascade;
alter table public.projects add column if not exists moderation text not null default 'approved'
  check (moderation in ('pending', 'approved', 'rejected'));
alter table public.projects add column if not exists moderation_note text check (char_length(moderation_note) <= 1000);
alter table public.projects add column if not exists contact_email text check (contact_email is null or contact_email ~* '^[^@\s]+@[^@\s]+\.[^@\s]+$');
alter table public.projects add column if not exists submitted_at timestamptz;
alter table public.projects drop constraint if exists project_has_owner;
alter table public.projects add constraint project_has_owner check (lab_id is not null or owner_id is not null);
create index if not exists projects_owner_idx on public.projects(owner_id);
create index if not exists projects_moderation_idx on public.projects(moderation) where moderation <> 'approved';

drop policy if exists "Projects are public" on public.projects;
create policy "Approved projects are public" on public.projects for select using (
  moderation = 'approved' or owner_id = auth.uid() or public.is_admin()
  or (lab_id is not null and public.is_lab_manager(lab_id))
);
create policy "Owners withdraw pending submissions" on public.projects for delete to authenticated
  using (owner_id = auth.uid() and lab_id is null and moderation <> 'approved');
-- lab managers may not touch moderation fields
revoke update on public.projects from authenticated;
grant update (kind, status, title, summary, tags, authors, year, github_url, demo_url, paper_url, sort_order, lab_id) on public.projects to authenticated;
revoke insert on public.projects from anon, authenticated;
grant insert (lab_id, kind, status, title, summary, tags, authors, year, github_url, demo_url, paper_url, sort_order) on public.projects to authenticated;

/* ───────────── permission helpers ───────────── */
create or replace function public.my_role_text()
returns text language sql stable security definer set search_path = public as $$
  select role::text from public.profiles where id = auth.uid()
$$;

create or replace function public.can_post_as_person()
returns boolean language sql stable security definer set search_path = public as $$
  select public.is_staff()   -- verified professor or admin
$$;

create or replace function public.can_act_as_host(p_lab uuid, p_company uuid, p_project uuid, p_person uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select public.can_act_as_host(p_lab, p_company, p_project)
      or (p_person is not null and p_person = auth.uid())
$$;

create or replace function public.can_manage_opportunity(p_opp uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select public.is_admin()
      or exists (select 1 from public.opportunities o where o.id = p_opp and o.created_by = auth.uid())
      or exists (select 1 from public.opportunity_hosts h where h.opportunity_id = p_opp
                 and public.can_act_as_host(h.lab_id, h.company_id, h.project_id, h.person_id))
$$;

create or replace function public.is_project_manager(p_project uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select public.is_admin() or exists (
    select 1 from public.projects p where p.id = p_project
      and ((p.lab_id is not null and public.is_lab_manager(p.lab_id)) or (p.owner_id = auth.uid() and p.moderation = 'approved'))
  )
$$;

/* ───────────── sign-up: PhD role ───────────── */
create or replace function public.handle_new_user()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  v_meta jsonb := coalesce(new.raw_user_meta_data, '{}'::jsonb);
  v_role text;
  v_company uuid;
  v_company_name text := nullif(trim(left(coalesce(v_meta->>'company', ''), 120)), '');
begin
  v_role := case
    when v_meta->>'role' = 'partner' then 'partner'
    when v_meta->>'role' in ('teacher', 'professor') and public.is_sdu_email(new.email) then 'teacher'
    when v_meta->>'role' = 'phd' and public.is_sdu_email(new.email) then 'phd'
    else 'student'
  end;

  insert into public.profiles (id, role, first_name, last_name, email, course, major, department, position, phone)
  values (
    new.id, v_role::public.app_role,
    left(coalesce(v_meta->>'first_name', ''), 100),
    left(coalesce(v_meta->>'last_name', ''), 100),
    lower(coalesce(new.email, '')),
    case when v_role in ('student', 'phd') and v_meta->>'course' ~ '^[1-6]$' then (v_meta->>'course')::smallint end,
    case when v_role in ('student', 'phd') then nullif(left(v_meta->>'major', 100), '') end,
    case when v_role in ('teacher', 'phd') then nullif(left(v_meta->>'department', 100), '') end,
    case when v_role = 'partner' then left(v_meta->>'position', 100) end,
    case when v_meta->>'phone' ~ '^[0-9 +()-]{6,24}$' then v_meta->>'phone' end
  )
  on conflict (id) do nothing;

  if v_role = 'partner' and v_company_name is not null then
    select id into v_company from public.companies where lower(name) = lower(v_company_name);
    if v_company is null then
      insert into public.companies (name, website)
      values (v_company_name, case when v_meta->>'website' ~* '^https?://' then left(v_meta->>'website', 200) end)
      returning id into v_company;
    end if;
    insert into public.company_members (company_id, user_id, role)
    values (v_company, new.id, case when exists (select 1 from public.company_members where company_id = v_company) then 'member' else 'owner' end)
    on conflict do nothing;
  end if;

  update public.lab_members m set user_id = new.id
    from public.lab_member_contacts c
   where c.member_id = m.id and c.email = lower(new.email) and m.user_id is null;

  update public.professors set profile_id = new.id where lower(email) = lower(new.email) and profile_id is null;
  return new;
end;
$$;

/* ───────────── applications: students and PhD students ───────────── */
create or replace function public.submit_application(p_opportunity uuid, p_note text, p_cv_path text default null)
returns public.applications language plpgsql security definer set search_path = public as $$
declare
  v_me public.profiles;
  v_opp public.opportunities;
  v_cv text;
  v_app public.applications;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED: sign in first'; end if;
  select * into v_me from public.profiles where id = auth.uid();
  if v_me.id is null then raise exception 'AUTH_REQUIRED: profile not found'; end if;
  if v_me.role::text not in ('student', 'phd') then raise exception 'STUDENTS_ONLY: only students and PhD students can apply'; end if;

  select * into v_opp from public.opportunities where id = p_opportunity;
  if v_opp.id is null then raise exception 'NOT_FOUND: opportunity'; end if;
  if not v_opp.is_active or (v_opp.deadline is not null and v_opp.deadline < current_date) then
    raise exception 'CLOSED: applications are closed';
  end if;
  if public.can_manage_opportunity(p_opportunity) and not public.is_admin() then
    raise exception 'OWN_LISTING: you manage this listing';
  end if;

  if p_cv_path is not null then
    if split_part(p_cv_path, '/', 1) <> auth.uid()::text
       or not exists (select 1 from storage.objects where bucket_id = 'cvs' and name = p_cv_path) then
      raise exception 'BAD_CV: upload the CV again';
    end if;
    v_cv := p_cv_path;
  else
    v_cv := v_me.cv_path;
  end if;
  if v_cv is null then raise exception 'CV_REQUIRED: upload your CV first'; end if;

  insert into public.applications (applicant_id, opportunity_id, note, cv_path)
  values (auth.uid(), p_opportunity, trim(p_note), v_cv)
  returning * into v_app;
  return v_app;
exception
  when unique_violation then raise exception 'DUPLICATE: you have already applied';
end;
$$;

/* ───────────── inbox with contacts ───────────── */
drop function if exists public.application_inbox();
create function public.application_inbox()
returns table (
  id uuid, status public.application_status, note text, reviewer_note text, created_at timestamptz, cv_path text,
  opportunity_id uuid, opportunity_title text, category public.opportunity_category, hosts text,
  applicant_id uuid, applicant_name text, applicant_email text, applicant_phone text, applicant_role text,
  applicant_course smallint, applicant_major text, applicant_department text
) language sql stable security definer set search_path = public as $$
  select a.id, a.status, a.note, a.reviewer_note, a.created_at, a.cv_path,
         o.id, o.title, o.category,
         (select string_agg(coalesce(l.name, c.name, pr.title, h.person_name), ' · ')
            from public.opportunity_hosts h
            left join public.labs l on l.id = h.lab_id
            left join public.companies c on c.id = h.company_id
            left join public.projects pr on pr.id = h.project_id
           where h.opportunity_id = o.id),
         p.id, trim(p.first_name || ' ' || p.last_name), p.email, p.phone, p.role::text,
         p.course, p.major, p.department
    from public.applications a
    join public.opportunities o on o.id = a.opportunity_id
    join public.profiles p on p.id = a.applicant_id
   where a.status <> 'withdrawn' and public.can_manage_opportunity(o.id)
   order by a.created_at desc
$$;

/* ───────────── save_opportunity: + post as myself (professor) ───────────── */
drop function if exists public.save_opportunity(uuid, public.opportunity_category, public.industrial_type, text, text, text[], text[], date, text, boolean, text, text, boolean, uuid[], uuid[], uuid[]);
create function public.save_opportunity(
  p_id uuid, p_category public.opportunity_category, p_industrial_type public.industrial_type,
  p_title text, p_description text, p_requirements text[], p_tags text[], p_deadline date, p_duration text,
  p_paid boolean, p_compensation text, p_work_format text, p_is_active boolean,
  p_lab_ids uuid[], p_company_ids uuid[], p_project_ids uuid[], p_as_me boolean default false
) returns uuid language plpgsql security definer set search_path = public as $$
declare v_id uuid; x uuid; v_name text; v_user text;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if coalesce(cardinality(p_lab_ids), 0) + coalesce(cardinality(p_company_ids), 0) + coalesce(cardinality(p_project_ids), 0) = 0
     and not coalesce(p_as_me, false) then
    raise exception 'NO_HOST: choose who offers this opportunity';
  end if;
  if coalesce(p_as_me, false) and not public.can_post_as_person() then
    raise exception 'NOT_ALLOWED: only verified professors can post opportunities in their own name';
  end if;
  foreach x in array coalesce(p_lab_ids, '{}') loop
    if not public.is_lab_manager(x) then raise exception 'NOT_ALLOWED: you do not manage one of the labs'; end if;
  end loop;
  foreach x in array coalesce(p_company_ids, '{}') loop
    if not public.is_company_member(x) then raise exception 'NOT_ALLOWED: you are not a member of one of the companies, or it is not verified yet'; end if;
  end loop;
  foreach x in array coalesce(p_project_ids, '{}') loop
    if not public.is_project_manager(x) then raise exception 'NOT_ALLOWED: you do not manage one of the projects'; end if;
  end loop;
  if p_category = 'industrial' and coalesce(cardinality(p_company_ids), 0) = 0 and not public.is_admin() then
    raise exception 'BAD_HOST: industrial cases are posted by a company';
  end if;

  if p_id is null then
    insert into public.opportunities (category, industrial_type, title, description, requirements, tags, deadline, duration, paid, compensation, work_format, is_active)
    values (p_category, case when p_category = 'industrial' then p_industrial_type end, trim(p_title), trim(p_description),
            coalesce(p_requirements, '{}'), coalesce(p_tags, '{}'), p_deadline, p_duration, coalesce(p_paid, false), p_compensation, p_work_format, coalesce(p_is_active, true))
    returning id into v_id;
  else
    if not public.can_manage_opportunity(p_id) then raise exception 'NOT_ALLOWED'; end if;
    update public.opportunities set category = p_category, industrial_type = case when p_category = 'industrial' then p_industrial_type end,
      title = trim(p_title), description = trim(p_description), requirements = coalesce(p_requirements, '{}'), tags = coalesce(p_tags, '{}'),
      deadline = p_deadline, duration = p_duration, paid = coalesce(p_paid, false), compensation = p_compensation,
      work_format = p_work_format, is_active = coalesce(p_is_active, true)
    where id = p_id;
    delete from public.opportunity_hosts where opportunity_id = p_id;
    v_id := p_id;
  end if;

  insert into public.opportunity_hosts (opportunity_id, lab_id) select v_id, unnest(coalesce(p_lab_ids, '{}'));
  insert into public.opportunity_hosts (opportunity_id, company_id) select v_id, unnest(coalesce(p_company_ids, '{}'));
  insert into public.opportunity_hosts (opportunity_id, project_id) select v_id, unnest(coalesce(p_project_ids, '{}'));
  if coalesce(p_as_me, false) then
    select trim(first_name || ' ' || last_name) into v_name from public.profiles where id = auth.uid();
    select username into v_user from public.professors where profile_id = auth.uid() limit 1;
    insert into public.opportunity_hosts (opportunity_id, person_id, person_name, person_username)
    values (v_id, auth.uid(), coalesce(nullif(v_name, ''), 'Professor'), v_user);
  end if;
  return v_id;
end;
$$;

/* ───────────── submissions: projects, startups, research ───────────── */
create or replace function public.submit_project(
  p_kind text, p_title text, p_summary text, p_tags text[], p_authors text[], p_year int, p_status text,
  p_github_url text, p_demo_url text, p_paper_url text, p_contact_email text
) returns public.projects language plpgsql security definer set search_path = public as $$
declare v_role text := public.my_role_text(); v_row public.projects; v_mod text;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED: sign in first'; end if;
  if v_role is null or v_role = 'partner' then raise exception 'NOT_ALLOWED: SDU accounts only'; end if;
  if p_kind not in ('research', 'startup', 'project') then raise exception 'BAD_KIND'; end if;
  if (select count(*) from public.projects where owner_id = auth.uid() and moderation = 'pending') >= 5 then
    raise exception 'TOO_MANY: wait until your pending submissions are reviewed';
  end if;
  -- PhD students publish research directly; everything else is reviewed by the SITAM office.
  v_mod := case when (v_role = 'phd' and p_kind = 'research') or v_role = 'admin' then 'approved' else 'pending' end;
  insert into public.projects (lab_id, owner_id, kind, status, title, summary, tags, authors, year,
                               github_url, demo_url, paper_url, contact_email, moderation, submitted_at)
  values (null, auth.uid(), p_kind::public.project_kind, coalesce(nullif(p_status, ''), 'ongoing')::public.project_status,
          trim(p_title), nullif(trim(p_summary), ''), coalesce(p_tags, '{}'), coalesce(p_authors, '{}'), p_year,
          nullif(p_github_url, ''), nullif(p_demo_url, ''), nullif(p_paper_url, ''), nullif(lower(p_contact_email), ''), v_mod, now())
  returning * into v_row;
  return v_row;
end;
$$;

create or replace function public.moderate_project(p_id uuid, p_decision text, p_note text default null)
returns public.projects language plpgsql security definer set search_path = public as $$
declare v_row public.projects;
begin
  if not public.is_admin() then raise exception 'NOT_ALLOWED: admins only'; end if;
  if p_decision not in ('approved', 'rejected', 'pending') then raise exception 'BAD_STATUS'; end if;
  update public.projects set moderation = p_decision, moderation_note = p_note
   where id = p_id and owner_id is not null
  returning * into v_row;
  if v_row.id is null then raise exception 'NOT_FOUND'; end if;
  return v_row;
end;
$$;

create or replace function public.moderation_queue()
returns table (id uuid, kind text, title text, summary text, tags text[], authors text[], year int, status text,
               github_url text, demo_url text, paper_url text, contact_email text, moderation text, submitted_at timestamptz,
               owner_id uuid, owner_name text, owner_email text, owner_role text)
language sql stable security definer set search_path = public as $$
  select p.id, p.kind::text, p.title, p.summary, p.tags, p.authors, p.year, p.status::text,
         p.github_url, p.demo_url, p.paper_url, p.contact_email, p.moderation, p.submitted_at,
         pr.id, trim(pr.first_name || ' ' || pr.last_name), pr.email, pr.role::text
    from public.projects p join public.profiles pr on pr.id = p.owner_id
   where public.is_admin() and p.owner_id is not null
   order by (p.moderation = 'pending') desc, p.submitted_at desc
$$;

/* ───────────── professor cards refresh from linked publications ───────────── */
create or replace function public.refresh_professor_metrics(p_prof uuid)
returns void language plpgsql security definer set search_path = public as $$
declare v_works int; v_cites int; v_h int; v_i10 int;
begin
  select count(*), coalesce(sum(p.citations), 0), count(*) filter (where p.citations >= 10)
    into v_works, v_cites, v_i10
    from public.publication_authors a join public.publications p on p.id = a.publication_id
   where a.professor_id = p_prof;
  select coalesce(max(rn), 0) into v_h from (
    select p.citations, row_number() over (order by p.citations desc) rn
      from public.publication_authors a join public.publications p on p.id = a.publication_id
     where a.professor_id = p_prof
  ) s where citations >= rn;
  -- Scopus totals can include works not imported here, so never lower them.
  update public.professors
     set total_works = greatest(total_works, v_works), total_citations = greatest(total_citations, v_cites),
         h_index = greatest(h_index, v_h), i10_index = greatest(i10_index, v_i10), updated_at = now()
   where id = p_prof;
end;
$$;

create or replace function public.publication_authors_refresh()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  perform public.refresh_professor_metrics(coalesce(new.professor_id, old.professor_id));
  return null;
end;
$$;
drop trigger if exists publication_authors_refresh on public.publication_authors;
create trigger publication_authors_refresh after insert or update or delete on public.publication_authors
  for each row execute function public.publication_authors_refresh();

create or replace function public.publications_refresh()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  perform public.refresh_professor_metrics(a.professor_id) from public.publication_authors a where a.publication_id = new.id;
  return null;
end;
$$;
drop trigger if exists publications_refresh on public.publications;
create trigger publications_refresh after update of citations on public.publications
  for each row execute function public.publications_refresh();

/* ───────────── my_context: role flags for the UI ───────────── */
create or replace function public.my_context()
returns jsonb language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'profile', (select to_jsonb(p) from public.profiles p where p.id = auth.uid()),
    'is_staff', public.is_staff(),
    'is_admin', public.is_admin(),
    'managed_labs', coalesce((
      select jsonb_agg(jsonb_build_object('id', l.id, 'slug', l.slug, 'name', l.name, 'role', m.role) order by l.name)
      from public.lab_members m join public.labs l on l.id = m.lab_id
      where m.user_id = auth.uid() and m.can_edit), '[]'::jsonb),
    'companies', coalesce((
      select jsonb_agg(jsonb_build_object('id', c.id, 'name', c.name, 'verified', c.verified) order by c.name)
      from public.company_members cm join public.companies c on c.id = cm.company_id
      where cm.user_id = auth.uid()), '[]'::jsonb),
    'professor', (select jsonb_build_object('username', username, 'full_name', full_name) from public.professors where profile_id = auth.uid() limit 1),
    'saved_labs', coalesce((select jsonb_agg(lab_id) from public.saved_labs where user_id = auth.uid()), '[]'::jsonb),
    'pending_moderation', case when public.is_admin()
      then (select count(*) from public.projects where moderation = 'pending' and owner_id is not null) else 0 end
  )
$$;

/* ───────────── function privileges ───────────── */
do $$
declare f text;
begin
  foreach f in array array[
    'my_context()', 'submit_application(uuid, text, text)', 'application_inbox()',
    'save_opportunity(uuid, public.opportunity_category, public.industrial_type, text, text, text[], text[], date, text, boolean, text, text, boolean, uuid[], uuid[], uuid[], boolean)',
    'submit_project(text, text, text, text[], text[], int, text, text, text, text, text)',
    'moderate_project(uuid, text, text)', 'moderation_queue()'
  ] loop
    execute format('revoke execute on function public.%s from anon, public', f);
    execute format('grant execute on function public.%s to authenticated', f);
  end loop;
end $$;
revoke execute on function public.refresh_professor_metrics(uuid) from anon, authenticated, public;

insert into sitam_meta.applied_migrations (version, name) values ('20261015100000', 'sitam_v3') on conflict do nothing;

-- ════════ 20261017100000_sitam_v4_leader_first ════════
/* SITAM SPACE v4 — leader-first labs
   ─────────────────────────────────────────────────────────────
   • Lab positions are separate from the platform role: a Student can be a Project
     Coordinator inside one lab. New positions: student_researcher, project_coordinator.
   • Management rights (lab_members.can_edit) follow the position and nothing else:
     lead · co_lead · student_lead · deputy_student_lead. Clients can no longer write
     can_edit, user_id or lab_id directly (column grants).
   • Only the lab lead / co-lead (or an admin) can add, change or remove lead / co-lead
     positions, or link an account to them. Student leads manage everyone else.
   • A manager cannot remove or demote themselves when nobody else could manage the lab.
   • Labs get "skills", a public contact e-mail and a first-setup marker.
   • my_context() also returns every lab the user belongs to (lab_memberships).
   • add_lab_member(): add a person by name and SDU e-mail; links the account if it exists.
   New enum values are compared as text inside functions, so the file runs in one transaction. */

alter type public.lab_role add value if not exists 'student_researcher';
alter type public.lab_role add value if not exists 'project_coordinator';

/* ───────────── labs: skills, contact, setup ───────────── */
alter table public.labs add column if not exists skills text[] not null default '{}';
alter table public.labs add column if not exists contact_email text
  check (contact_email is null or contact_email ~* '^[^@\s]+@[^@\s]+\.[^@\s]+$');
alter table public.labs add column if not exists setup_completed_at timestamptz;

/* ───────────── helpers ───────────── */
create or replace function public.is_lab_head_role(p_role text)
returns boolean language sql immutable as $$
  select p_role in ('lead', 'co_lead')
$$;

create or replace function public.is_manager_role(p_role text)
returns boolean language sql immutable as $$
  select p_role in ('lead', 'co_lead', 'student_lead', 'deputy_student_lead')
$$;

-- Lab lead / co-lead with a linked account (or admin): may manage the head positions.
create or replace function public.is_lab_head(p_lab uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select public.is_admin() or exists (
    select 1 from public.lab_members m
     where m.lab_id = p_lab and m.user_id = auth.uid() and public.is_lab_head_role(m.role::text)
  )
$$;

/* ───────────── can_edit follows the position ───────────── */
create or replace function public.lab_members_defaults()
returns trigger language plpgsql as $$
declare v_trusted boolean := auth.uid() is null or public.is_admin();
begin
  if tg_op = 'INSERT' then
    if public.is_manager_role(new.role::text) then new.can_edit := true;
    elsif not v_trusted then new.can_edit := false;
    end if;
  elsif new.role is distinct from old.role then
    new.can_edit := public.is_manager_role(new.role::text);
  elsif new.can_edit is distinct from old.can_edit and not v_trusted then
    new.can_edit := old.can_edit;   -- only admins / migrations grant rights outside a position
  end if;
  if new.role::text = 'former_lead' then new.can_edit := false; end if;
  return new;
end;
$$;

/* ───────────── hierarchy guard (runs for every write path: editor, RPCs, triggers) ───────────── */
create or replace function public.lab_members_guard()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := auth.uid();
  v_lab uuid := coalesce(new.lab_id, old.lab_id);
  v_head boolean;
begin
  -- sign-up linking, migrations and admins are trusted
  if v_uid is null or public.is_admin() then
    return case when tg_op = 'DELETE' then old else new end;
  end if;
  v_head := public.is_lab_head(v_lab);

  if tg_op = 'UPDATE' and new.lab_id is distinct from old.lab_id then
    raise exception 'NOT_ALLOWED: a member cannot be moved to another lab';
  end if;

  -- lead / co-lead rows are protected from everyone below them
  if not v_head then
    if tg_op = 'DELETE' and public.is_lab_head_role(old.role::text) then
      raise exception 'NOT_ALLOWED: only the lab lead or co-lead can remove a lead position';
    end if;
    if tg_op = 'INSERT' and public.is_lab_head_role(new.role::text) then
      raise exception 'NOT_ALLOWED: only the lab lead or co-lead can assign a lead position';
    end if;
    if tg_op = 'UPDATE' and (public.is_lab_head_role(old.role::text) or public.is_lab_head_role(new.role::text))
       and (new.role, new.full_name, new.title, new.term, new.user_id) is distinct from (old.role, old.full_name, old.title, old.term, old.user_id) then
      raise exception 'NOT_ALLOWED: only the lab lead or co-lead can change a lead position';
    end if;
  end if;

  -- never leave a lab without anyone who can manage it
  if tg_op in ('DELETE', 'UPDATE') and old.user_id = v_uid and old.can_edit
     and (tg_op = 'DELETE' or not public.is_manager_role(new.role::text))
     and not exists (select 1 from public.lab_members m
                      where m.lab_id = v_lab and m.id <> old.id and m.user_id is not null and m.can_edit) then
    raise exception 'LAST_MANAGER: give another member a lead position before you step down';
  end if;

  return case when tg_op = 'DELETE' then old else new end;
end;
$$;

drop trigger if exists lab_members_guard on public.lab_members;
create trigger lab_members_guard before insert or update or delete on public.lab_members
  for each row execute function public.lab_members_guard();

-- Contact e-mails link existing accounts — but a student lead cannot link someone to a lead position.
create or replace function public.lab_member_contacts_link()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.email is not null then
    update public.lab_members m set user_id = p.id
      from public.profiles p
     where m.id = new.member_id and m.user_id is null and p.email = new.email
       and not exists (select 1 from public.lab_members x where x.lab_id = m.lab_id and x.user_id = p.id)
       and (not public.is_lab_head_role(m.role::text) or auth.uid() is null or public.is_lab_head(m.lab_id));
  end if;
  return new;
end;
$$;

/* ───────────── clients write only plain fields ───────────── */
revoke insert, update on public.lab_members from anon, authenticated;
grant insert (lab_id, full_name, title, role, term, sort_order) on public.lab_members to authenticated;
grant update (full_name, title, role, term, sort_order) on public.lab_members to authenticated;
grant delete on public.lab_members to authenticated;

/* ───────────── add a person (links the account when it exists) ───────────── */
create or replace function public.add_lab_member(p_lab uuid, p_full_name text, p_email text, p_role text, p_title text default null)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_email text := nullif(lower(trim(coalesce(p_email, ''))), '');
  v_profile public.profiles;
  v_name text := nullif(trim(coalesce(p_full_name, '')), '');
  v_id uuid;
  v_linked boolean := false;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED: sign in first'; end if;
  if not public.is_lab_manager(p_lab) then raise exception 'NOT_ALLOWED: you do not manage this lab'; end if;
  if p_role is null or p_role = 'former_lead' or p_role not in
     ('lead', 'co_lead', 'student_lead', 'deputy_student_lead', 'member', 'research_assistant', 'student_researcher', 'project_coordinator') then
    raise exception 'BAD_ROLE: choose a position';
  end if;
  if v_email is not null and v_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then raise exception 'BAD_EMAIL: check the e-mail address'; end if;

  if v_email is not null then
    select * into v_profile from public.profiles where email = v_email;
    if v_profile.id is not null then
      if exists (select 1 from public.lab_members where lab_id = p_lab and user_id = v_profile.id) then
        raise exception 'DUPLICATE: this person is already in the lab';
      end if;
      v_name := coalesce(v_name, nullif(trim(v_profile.first_name || ' ' || v_profile.last_name), ''));
    end if;
  end if;
  if v_name is null or char_length(v_name) < 2 then raise exception 'NAME_REQUIRED: enter the full name'; end if;

  insert into public.lab_members (lab_id, user_id, full_name, title, role, sort_order)
  values (p_lab, v_profile.id, left(v_name, 120), nullif(left(trim(coalesce(p_title, '')), 200), ''), p_role::public.lab_role,
          coalesce((select max(sort_order) + 1 from public.lab_members where lab_id = p_lab), 0))
  returning id into v_id;
  v_linked := v_profile.id is not null;
  if v_email is not null then
    insert into public.lab_member_contacts (member_id, email) values (v_id, v_email)
    on conflict (member_id) do update set email = excluded.email;
  end if;
  return jsonb_build_object('id', v_id, 'linked', v_linked);
end;
$$;

/* ───────────── my_context: memberships for the leader-first UI ───────────── */
create or replace function public.my_context()
returns jsonb language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'profile', (select to_jsonb(p) from public.profiles p where p.id = auth.uid()),
    'is_staff', public.is_staff(),
    'is_admin', public.is_admin(),
    'managed_labs', coalesce((
      select jsonb_agg(jsonb_build_object('id', l.id, 'slug', l.slug, 'name', l.name, 'role', m.role) order by l.name)
      from public.lab_members m join public.labs l on l.id = m.lab_id
      where m.user_id = auth.uid() and m.can_edit), '[]'::jsonb),
    'lab_memberships', coalesce((
      select jsonb_agg(jsonb_build_object('id', l.id, 'slug', l.slug, 'name', l.name, 'role', m.role, 'title', m.title,
                                          'can_edit', m.can_edit, 'is_head', public.is_lab_head_role(m.role::text)) order by l.name)
      from public.lab_members m join public.labs l on l.id = m.lab_id
      where m.user_id = auth.uid() and m.role::text <> 'former_lead'), '[]'::jsonb),
    'companies', coalesce((
      select jsonb_agg(jsonb_build_object('id', c.id, 'name', c.name, 'verified', c.verified) order by c.name)
      from public.company_members cm join public.companies c on c.id = cm.company_id
      where cm.user_id = auth.uid()), '[]'::jsonb),
    'professor', (select jsonb_build_object('username', username, 'full_name', full_name) from public.professors where profile_id = auth.uid() limit 1),
    'saved_labs', coalesce((select jsonb_agg(lab_id) from public.saved_labs where user_id = auth.uid()), '[]'::jsonb),
    'pending_moderation', case when public.is_admin()
      then (select count(*) from public.projects where moderation = 'pending' and owner_id is not null) else 0 end
  )
$$;

/* ───────────── function privileges ───────────── */
revoke execute on function public.add_lab_member(uuid, text, text, text, text) from anon, public;
grant execute on function public.add_lab_member(uuid, text, text, text, text) to authenticated;
revoke execute on function public.my_context() from anon, public;
grant execute on function public.my_context() to authenticated;
grant execute on function public.is_lab_head(uuid) to authenticated;

insert into sitam_meta.applied_migrations (version, name) values ('20261017100000', 'sitam_v4_leader_first') on conflict do nothing;

-- ════════ 20261018100000_sitam_v5_roles ════════
/* SITAM SPACE v5 — multiple roles, Lab Head requests, public contacts
   ─────────────────────────────────────────────────────────────
   • One account, several roles: the primary university role (profiles.role) never changes
     because of lab positions. Lab Head status is an extra role per laboratory.
   • Lab Head status is REQUESTED (at registration or later from the profile) for an existing
     lab and APPROVED by an admin. Nobody can create a lab this way.
   • New lab position: mentor (no management rights).
   • Contacts: every registered person's e-mail is visible to signed-in users (public_people),
     so people can write to each other directly. Professors' Scopus e-mail too.
   New enum values are compared as text inside functions, so the file runs in one transaction. */

alter type public.lab_role add value if not exists 'mentor';

/* ───────────── Lab Head requests ───────────── */
create table if not exists public.lab_head_requests (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.profiles(id) on delete cascade,
  lab_id uuid not null references public.labs(id) on delete cascade,
  position text not null default 'lead' check (position in ('lead', 'co_lead')),
  note text check (char_length(note) <= 500),
  status text not null default 'pending' check (status in ('pending', 'approved', 'rejected', 'cancelled')),
  decision_note text check (char_length(decision_note) <= 500),
  decided_by uuid references public.profiles(id) on delete set null,
  decided_at timestamptz,
  created_at timestamptz not null default now()
);
create unique index if not exists lab_head_requests_one_pending on public.lab_head_requests(user_id, lab_id) where status = 'pending';
create index if not exists lab_head_requests_status_idx on public.lab_head_requests(status);

alter table public.lab_head_requests enable row level security;
drop policy if exists "Own lab head requests" on public.lab_head_requests;
create policy "Own lab head requests" on public.lab_head_requests for select to authenticated
  using (user_id = auth.uid() or public.is_admin());
revoke insert, update, delete on public.lab_head_requests from anon, authenticated;
grant select on public.lab_head_requests to authenticated;

create or replace function public.request_lab_head(p_lab uuid, p_position text default 'lead', p_note text default null)
returns public.lab_head_requests language plpgsql security definer set search_path = public as $$
declare v_role text := public.my_role_text(); v_row public.lab_head_requests;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED: sign in first'; end if;
  if v_role is null or v_role = 'partner' then raise exception 'NOT_ALLOWED: only SDU accounts can head a lab'; end if;
  if coalesce(p_position, 'lead') not in ('lead', 'co_lead') then raise exception 'BAD_ROLE: choose lab head or co-head'; end if;
  if not exists (select 1 from public.labs where id = p_lab) then raise exception 'NOT_FOUND: choose an existing laboratory'; end if;
  if exists (select 1 from public.lab_members m where m.lab_id = p_lab and m.user_id = auth.uid() and public.is_lab_head_role(m.role::text)) then
    raise exception 'DUPLICATE: you already head this lab';
  end if;
  insert into public.lab_head_requests (user_id, lab_id, position, note)
  values (auth.uid(), p_lab, coalesce(p_position, 'lead'), nullif(left(trim(coalesce(p_note, '')), 500), ''))
  returning * into v_row;
  return v_row;
exception
  when unique_violation then raise exception 'DUPLICATE: your request for this lab is already waiting for approval';
end;
$$;

create or replace function public.cancel_lab_head_request(p_id uuid)
returns void language plpgsql security definer set search_path = public as $$
begin
  update public.lab_head_requests set status = 'cancelled', decided_at = now()
   where id = p_id and user_id = auth.uid() and status = 'pending';
  if not found then raise exception 'NOT_ALLOWED: this request cannot be cancelled'; end if;
end;
$$;

-- Admin decision. Approval links the person to the lab in the requested head position;
-- the position (not this function) gives the management rights (lab_members_defaults).
create or replace function public.decide_lab_head_request(p_id uuid, p_approve boolean, p_note text default null)
returns public.lab_head_requests language plpgsql security definer set search_path = public as $$
declare v_req public.lab_head_requests; v_name text; v_member uuid;
begin
  if not public.is_admin() then raise exception 'NOT_ALLOWED: only the SITAM office approves lab heads'; end if;
  select * into v_req from public.lab_head_requests where id = p_id for update;
  if v_req.id is null then raise exception 'NOT_FOUND: request'; end if;
  if v_req.status <> 'pending' then raise exception 'NOT_ALLOWED: this request was already decided'; end if;

  update public.lab_head_requests
     set status = case when p_approve then 'approved' else 'rejected' end,
         decision_note = nullif(left(trim(coalesce(p_note, '')), 500), ''), decided_by = auth.uid(), decided_at = now()
   where id = p_id returning * into v_req;

  if p_approve then
    select coalesce(nullif(trim(first_name || ' ' || last_name), ''), email) into v_name from public.profiles where id = v_req.user_id;
    select id into v_member from public.lab_members where lab_id = v_req.lab_id and user_id = v_req.user_id;
    if v_member is not null then
      update public.lab_members set role = v_req.position::public.lab_role where id = v_member;
    else
      -- the lab form may already list this person by name in that position
      select id into v_member from public.lab_members
       where lab_id = v_req.lab_id and user_id is null and role::text = v_req.position and lower(full_name) = lower(v_name)
       limit 1;
      if v_member is not null then
        update public.lab_members set user_id = v_req.user_id where id = v_member;
      else
        insert into public.lab_members (lab_id, user_id, full_name, role, sort_order)
        values (v_req.lab_id, v_req.user_id, left(v_name, 120), v_req.position::public.lab_role, -1);
      end if;
    end if;
  end if;
  return v_req;
end;
$$;

create or replace function public.lab_head_queue()
returns table (id uuid, status text, head_position text, note text, created_at timestamptz, decision_note text,
               user_id uuid, user_name text, user_email text, user_role text, user_department text,
               lab_id uuid, lab_name text, lab_slug text, lab_has_head boolean)
language sql stable security definer set search_path = public as $$
  select r.id, r.status, r.position, r.note, r.created_at, r.decision_note,
         p.id, trim(p.first_name || ' ' || p.last_name), p.email, p.role::text, p.department,
         l.id, l.name, l.slug,
         exists (select 1 from public.lab_members m where m.lab_id = l.id and m.user_id is not null and public.is_lab_head_role(m.role::text))
    from public.lab_head_requests r
    join public.profiles p on p.id = r.user_id
    join public.labs l on l.id = r.lab_id
   where public.is_admin()
   order by (r.status = 'pending') desc, r.created_at desc
   limit 200
$$;

/* ───────────── sign-up: optional Lab Head request (existing lab only) ───────────── */
create or replace function public.handle_new_user()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  v_meta jsonb := coalesce(new.raw_user_meta_data, '{}'::jsonb);
  v_role text;
  v_company uuid;
  v_company_name text := nullif(trim(left(coalesce(v_meta->>'company', ''), 120)), '');
  v_lab uuid;
begin
  v_role := case
    when v_meta->>'role' = 'partner' then 'partner'
    when v_meta->>'role' in ('teacher', 'professor') and public.is_sdu_email(new.email) then 'teacher'
    when v_meta->>'role' = 'phd' and public.is_sdu_email(new.email) then 'phd'
    else 'student'
  end;

  insert into public.profiles (id, role, first_name, last_name, email, course, major, department, position, phone)
  values (
    new.id, v_role::public.app_role,
    left(coalesce(v_meta->>'first_name', ''), 100),
    left(coalesce(v_meta->>'last_name', ''), 100),
    lower(coalesce(new.email, '')),
    case when v_role in ('student', 'phd') and v_meta->>'course' ~ '^[1-6]$' then (v_meta->>'course')::smallint end,
    case when v_role in ('student', 'phd') then nullif(left(v_meta->>'major', 100), '') end,
    case when v_role in ('teacher', 'phd') then nullif(left(v_meta->>'department', 100), '') end,
    case when v_role = 'partner' then left(v_meta->>'position', 100) end,
    case when v_meta->>'phone' ~ '^[0-9 +()-]{6,24}$' then v_meta->>'phone' end
  )
  on conflict (id) do nothing;

  if v_role = 'partner' and v_company_name is not null then
    select id into v_company from public.companies where lower(name) = lower(v_company_name);
    if v_company is null then
      insert into public.companies (name, website)
      values (v_company_name, case when v_meta->>'website' ~* '^https?://' then left(v_meta->>'website', 200) end)
      returning id into v_company;
    end if;
    insert into public.company_members (company_id, user_id, role)
    values (v_company, new.id, case when exists (select 1 from public.company_members where company_id = v_company) then 'member' else 'owner' end)
    on conflict do nothing;
  end if;

  -- People listed in a lab form by e-mail (entered by the SITAM office / lab heads) are linked at once.
  update public.lab_members m set user_id = new.id
    from public.lab_member_contacts c
   where c.member_id = m.id and c.email = lower(new.email) and m.user_id is null;

  update public.professors set profile_id = new.id where lower(email) = lower(new.email) and profile_id is null;

  -- "I am the head of an existing laboratory": a request for the admin, never a new lab.
  if v_role <> 'partner' and coalesce(v_meta->>'lab_head_lab', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    select id into v_lab from public.labs where id = (v_meta->>'lab_head_lab')::uuid;
    if v_lab is not null and not exists (
      select 1 from public.lab_members m where m.lab_id = v_lab and m.user_id = new.id and public.is_lab_head_role(m.role::text)
    ) then
      insert into public.lab_head_requests (user_id, lab_id, position, note)
      values (new.id, v_lab, case when v_meta->>'lab_head_position' = 'co_lead' then 'co_lead' else 'lead' end, 'Requested at registration')
      on conflict do nothing;
    end if;
  end if;
  return new;
end;
$$;

/* ───────────── positions: mentor ───────────── */
create or replace function public.add_lab_member(p_lab uuid, p_full_name text, p_email text, p_role text, p_title text default null)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_email text := nullif(lower(trim(coalesce(p_email, ''))), '');
  v_profile public.profiles;
  v_name text := nullif(trim(coalesce(p_full_name, '')), '');
  v_id uuid;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED: sign in first'; end if;
  if not public.is_lab_manager(p_lab) then raise exception 'NOT_ALLOWED: you do not manage this lab'; end if;
  if p_role is null or p_role not in
     ('lead', 'co_lead', 'student_lead', 'deputy_student_lead', 'member', 'mentor', 'research_assistant', 'student_researcher', 'project_coordinator') then
    raise exception 'BAD_ROLE: choose a position';
  end if;
  if v_email is not null and v_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then raise exception 'BAD_EMAIL: check the e-mail address'; end if;

  if v_email is not null then
    select * into v_profile from public.profiles where email = v_email;
    if v_profile.id is not null then
      if exists (select 1 from public.lab_members where lab_id = p_lab and user_id = v_profile.id) then
        raise exception 'DUPLICATE: this person is already in the lab';
      end if;
      v_name := coalesce(v_name, nullif(trim(v_profile.first_name || ' ' || v_profile.last_name), ''));
    end if;
  end if;
  if v_name is null or char_length(v_name) < 2 then raise exception 'NAME_REQUIRED: enter the full name'; end if;

  insert into public.lab_members (lab_id, user_id, full_name, title, role, sort_order)
  values (p_lab, v_profile.id, left(v_name, 120), nullif(left(trim(coalesce(p_title, '')), 200), ''), p_role::public.lab_role,
          coalesce((select max(sort_order) + 1 from public.lab_members where lab_id = p_lab), 0))
  returning id into v_id;
  if v_email is not null then
    insert into public.lab_member_contacts (member_id, email) values (v_id, v_email)
    on conflict (member_id) do update set email = excluded.email;
  end if;
  return jsonb_build_object('id', v_id, 'linked', v_profile.id is not null);
end;
$$;

/* ───────────── contacts everyone can use ───────────── */
-- Name, primary role, study / work details and e-mail of registered people (no phone, no CV).
-- The view runs with its owner's rights, so it is the only way to read other people's profiles.
create or replace view public.public_people as
  select p.id, p.first_name, p.last_name, p.role::text as role, p.email, p.course, p.major, p.department, p.position, p.bio
    from public.profiles p;
revoke all on public.public_people from anon, public;
grant select on public.public_people to authenticated;

grant select (email) on public.professors to authenticated;

/* ───────────── my_context: + Lab Head requests ───────────── */
create or replace function public.my_context()
returns jsonb language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'profile', (select to_jsonb(p) from public.profiles p where p.id = auth.uid()),
    'is_staff', public.is_staff(),
    'is_admin', public.is_admin(),
    'managed_labs', coalesce((
      select jsonb_agg(jsonb_build_object('id', l.id, 'slug', l.slug, 'name', l.name, 'role', m.role) order by l.name)
      from public.lab_members m join public.labs l on l.id = m.lab_id
      where m.user_id = auth.uid() and m.can_edit), '[]'::jsonb),
    'lab_memberships', coalesce((
      select jsonb_agg(jsonb_build_object('id', l.id, 'slug', l.slug, 'name', l.name, 'role', m.role, 'title', m.title,
                                          'can_edit', m.can_edit, 'is_head', public.is_lab_head_role(m.role::text)) order by l.name)
      from public.lab_members m join public.labs l on l.id = m.lab_id
      where m.user_id = auth.uid() and m.role::text <> 'former_lead'), '[]'::jsonb),
    'lab_head_requests', coalesce((
      select jsonb_agg(jsonb_build_object('id', r.id, 'lab_id', r.lab_id, 'lab_name', l.name, 'position', r.position,
                                          'status', r.status, 'decision_note', r.decision_note, 'created_at', r.created_at) order by r.created_at desc)
      from public.lab_head_requests r join public.labs l on l.id = r.lab_id
      where r.user_id = auth.uid() and r.status in ('pending', 'rejected')), '[]'::jsonb),
    'companies', coalesce((
      select jsonb_agg(jsonb_build_object('id', c.id, 'name', c.name, 'verified', c.verified) order by c.name)
      from public.company_members cm join public.companies c on c.id = cm.company_id
      where cm.user_id = auth.uid()), '[]'::jsonb),
    'professor', (select jsonb_build_object('username', username, 'full_name', full_name) from public.professors where profile_id = auth.uid() limit 1),
    'saved_labs', coalesce((select jsonb_agg(lab_id) from public.saved_labs where user_id = auth.uid()), '[]'::jsonb),
    'pending_moderation', case when public.is_admin()
      then (select count(*) from public.projects where moderation = 'pending' and owner_id is not null) else 0 end,
    'pending_lab_heads', case when public.is_admin() then (select count(*) from public.lab_head_requests where status = 'pending') else 0 end
  )
$$;

/* ───────────── function privileges ───────────── */
do $$
declare f text;
begin
  foreach f in array array[
    'request_lab_head(uuid, text, text)', 'cancel_lab_head_request(uuid)', 'decide_lab_head_request(uuid, boolean, text)',
    'lab_head_queue()', 'add_lab_member(uuid, text, text, text, text)', 'my_context()'
  ] loop
    execute format('revoke execute on function public.%s from anon, public', f);
    execute format('grant execute on function public.%s to authenticated', f);
  end loop;
end $$;

insert into sitam_meta.applied_migrations (version, name) values ('20261018100000', 'sitam_v5_roles') on conflict do nothing;

-- ════════ 20261019100000_sitam_v7_coordinator ════════
/* SITAM SPACE v7 — Google sign-in, coordinator, head / member
   ─────────────────────────────────────────────────────────────
   • Account type is detected from the SDU e-mail at sign-up (Google OAuth):
       local part starts with digits (230183076@sdu.edu.kz) → student, otherwise → teacher.
   • Coordinator = e-mail listed in coordinator_emails (server-side config, not selectable).
     The coordinator is an admin: manages labs and is the ONLY one who assigns / removes lab heads.
   • Inside a lab there are two levels: head (lead / co_lead) and member (any other position).
     Only heads manage the lab: info, members, projects, events. Everyone else is read-only.
   • Profile: faculty, group / department, photo.
   • "Academic / Education" category → "Courses". Startups are gone (lab startups become projects).
   • Projects and events are created by lab heads only (student submissions and Lab Head requests are closed).
   New enum values are compared as text inside functions, so the file runs in one transaction. */

/* ───────────── coordinator (server config) ───────────── */
create table if not exists public.coordinator_emails (
  email text primary key check (email = lower(email))
);
alter table public.coordinator_emails enable row level security;
revoke all on public.coordinator_emails from anon, authenticated;
insert into public.coordinator_emails (email) values ('230183076@sdu.edu.kz') on conflict do nothing;

create or replace function public.is_coordinator()
returns boolean language sql stable security definer set search_path = public as $$
  select coalesce((
    select exists (select 1 from public.coordinator_emails c where c.email = lower(p.email))
      from public.profiles p where p.id = auth.uid()
  ), false)
$$;

-- The coordinator gets every admin power (labs, heads, verification).
create or replace function public.is_admin()
returns boolean language sql stable security definer set search_path = public as $$
  select coalesce((select role = 'admin' from public.profiles where id = auth.uid()), false) or public.is_coordinator()
$$;

/* ───────────── profile fields ───────────── */
alter table public.profiles add column if not exists faculty text check (char_length(faculty) <= 120);
alter table public.profiles add column if not exists group_name text check (char_length(group_name) <= 120);
alter table public.profiles add column if not exists avatar_url text check (avatar_url is null or avatar_url ~* '^https://');
grant update (faculty, group_name, avatar_url) on public.profiles to authenticated;

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('avatars', 'avatars', true, 3145728, array['image/png', 'image/jpeg', 'image/webp'])
on conflict (id) do nothing;
drop policy if exists "Own avatar upload" on storage.objects;
drop policy if exists "Own avatar update" on storage.objects;
drop policy if exists "Own avatar delete" on storage.objects;
create policy "Own avatar upload" on storage.objects for insert to authenticated
  with check (bucket_id = 'avatars' and (storage.foldername(name))[1] = auth.uid()::text);
create policy "Own avatar update" on storage.objects for update to authenticated
  using (bucket_id = 'avatars' and (storage.foldername(name))[1] = auth.uid()::text);
create policy "Own avatar delete" on storage.objects for delete to authenticated
  using (bucket_id = 'avatars' and (storage.foldername(name))[1] = auth.uid()::text);

create or replace view public.public_people as
  select p.id, p.first_name, p.last_name, p.role::text as role, p.email, p.course, p.major, p.department, p.position, p.bio,
         p.faculty, p.group_name, p.avatar_url
    from public.profiles p;
revoke all on public.public_people from anon, public;
grant select on public.public_people to authenticated;

/* ───────────── sign-up: type from the e-mail ───────────── */
create or replace function public.account_type_from_email(p_email text)
returns text language sql immutable as $$
  select case when split_part(lower(coalesce(p_email, '')), '@', 1) ~ '^[0-9]' then 'student' else 'teacher' end
$$;

create or replace function public.handle_new_user()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  v_meta jsonb := coalesce(new.raw_user_meta_data, '{}'::jsonb);
  v_role text;
  v_company uuid;
  v_company_name text := nullif(trim(left(coalesce(v_meta->>'company', ''), 120)), '');
  v_full text := trim(coalesce(v_meta->>'full_name', v_meta->>'name', ''));
  v_first text := nullif(trim(coalesce(v_meta->>'first_name', v_meta->>'given_name', '')), '');
  v_last text := nullif(trim(coalesce(v_meta->>'last_name', v_meta->>'family_name', '')), '');
  v_avatar text := coalesce(v_meta->>'avatar_url', v_meta->>'picture');
begin
  -- Industry partners (invited, e-mail sign-in) keep their type; SDU accounts get it from the e-mail.
  v_role := case when v_meta->>'role' = 'partner' and not public.is_sdu_email(new.email) then 'partner'
                 else public.account_type_from_email(new.email) end;
  if v_first is null and v_full <> '' then
    v_first := split_part(v_full, ' ', 1);
    v_last := coalesce(v_last, nullif(trim(substr(v_full, char_length(split_part(v_full, ' ', 1)) + 1)), ''));
  end if;

  insert into public.profiles (id, role, first_name, last_name, email, avatar_url)
  values (new.id, v_role::public.app_role, left(coalesce(v_first, ''), 100), left(coalesce(v_last, ''), 100),
          lower(coalesce(new.email, '')), case when v_avatar ~* '^https://' then left(v_avatar, 500) end)
  on conflict (id) do nothing;

  if v_role = 'partner' and v_company_name is not null then
    select id into v_company from public.companies where lower(name) = lower(v_company_name);
    if v_company is null then
      insert into public.companies (name, website)
      values (v_company_name, case when v_meta->>'website' ~* '^https?://' then left(v_meta->>'website', 200) end)
      returning id into v_company;
    end if;
    insert into public.company_members (company_id, user_id, role)
    values (v_company, new.id, case when exists (select 1 from public.company_members where company_id = v_company) then 'member' else 'owner' end)
    on conflict do nothing;
  end if;

  -- People the lab form lists by e-mail become members of that lab (positions set by the coordinator stay as they are).
  update public.lab_members m set user_id = new.id
    from public.lab_member_contacts c
   where c.member_id = m.id and c.email = lower(new.email) and m.user_id is null;
  update public.professors set profile_id = new.id where lower(email) = lower(new.email) and profile_id is null;
  return new;
end;
$$;

/* ───────────── head / member ───────────── */
-- Management rights belong to heads only.
create or replace function public.is_manager_role(p_role text)
returns boolean language sql immutable as $$
  select p_role in ('lead', 'co_lead')
$$;
update public.lab_members set can_edit = public.is_manager_role(role::text) where can_edit is distinct from public.is_manager_role(role::text);

-- Only the coordinator (admin) assigns, changes or removes heads. Heads manage members.
create or replace function public.lab_members_guard()
returns trigger language plpgsql security definer set search_path = public as $$
declare v_uid uuid := auth.uid(); v_lab uuid := coalesce(new.lab_id, old.lab_id);
begin
  if v_uid is null or public.is_admin() then
    return case when tg_op = 'DELETE' then old else new end;
  end if;
  if tg_op = 'UPDATE' and new.lab_id is distinct from old.lab_id then
    raise exception 'NOT_ALLOWED: a member cannot be moved to another lab';
  end if;
  if tg_op = 'INSERT' and public.is_lab_head_role(new.role::text) then
    raise exception 'NOT_ALLOWED: only the coordinator assigns lab heads';
  end if;
  if tg_op = 'DELETE' and public.is_lab_head_role(old.role::text) then
    raise exception 'NOT_ALLOWED: only the coordinator removes lab heads';
  end if;
  if tg_op = 'UPDATE' and (public.is_lab_head_role(old.role::text) or public.is_lab_head_role(new.role::text))
     and (new.role is distinct from old.role or new.user_id is distinct from old.user_id) then
    raise exception 'NOT_ALLOWED: only the coordinator assigns or removes lab heads';
  end if;
  return case when tg_op = 'DELETE' then old else new end;
end;
$$;

create or replace function public.lab_member_contacts_link()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.email is not null then
    update public.lab_members m set user_id = p.id
      from public.profiles p
     where m.id = new.member_id and m.user_id is null and p.email = new.email
       and not exists (select 1 from public.lab_members x where x.lab_id = m.lab_id and x.user_id = p.id)
       and (not public.is_lab_head_role(m.role::text) or auth.uid() is null or public.is_admin());
  end if;
  return new;
end;
$$;

-- Heads add registered people as members (any non-head position).
create or replace function public.add_lab_member(p_lab uuid, p_full_name text, p_email text, p_role text, p_title text default null)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_email text := nullif(lower(trim(coalesce(p_email, ''))), '');
  v_profile public.profiles;
  v_name text := nullif(trim(coalesce(p_full_name, '')), '');
  v_id uuid;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED: sign in first'; end if;
  if not public.is_lab_manager(p_lab) then raise exception 'NOT_ALLOWED: only the head of this lab can add members'; end if;
  if coalesce(p_role, 'member') not in ('member', 'mentor', 'research_assistant', 'student_researcher', 'project_coordinator') then
    raise exception 'BAD_ROLE: heads are assigned by the coordinator';
  end if;
  if v_email is null then raise exception 'EMAIL_REQUIRED: choose a registered user'; end if;
  select * into v_profile from public.profiles where email = v_email;
  if v_profile.id is null then raise exception 'NOT_FOUND: this person has not signed in to SITAM SPACE yet'; end if;
  if exists (select 1 from public.lab_members where lab_id = p_lab and user_id = v_profile.id) then
    raise exception 'DUPLICATE: this person is already in the lab';
  end if;
  v_name := coalesce(nullif(trim(v_profile.first_name || ' ' || v_profile.last_name), ''), v_name, v_profile.email);

  insert into public.lab_members (lab_id, user_id, full_name, title, role, sort_order)
  values (p_lab, v_profile.id, left(v_name, 120), nullif(left(trim(coalesce(p_title, '')), 200), ''),
          coalesce(p_role, 'member')::public.lab_role,
          coalesce((select max(sort_order) + 1 from public.lab_members where lab_id = p_lab), 0))
  returning id into v_id;
  insert into public.lab_member_contacts (member_id, email) values (v_id, v_email)
  on conflict (member_id) do update set email = excluded.email;
  return jsonb_build_object('id', v_id, 'linked', true);
end;
$$;

/* ───────────── coordinator tools ───────────── */
create or replace function public.admin_create_lab(p_name text, p_focus text[] default '{}')
returns public.labs language plpgsql security definer set search_path = public as $$
declare v_slug text; v_base text; n int := 1; v_row public.labs;
begin
  if not public.is_admin() then raise exception 'NOT_ALLOWED: coordinator only'; end if;
  if char_length(trim(coalesce(p_name, ''))) < 2 then raise exception 'NAME_REQUIRED: enter the lab name'; end if;
  v_base := left(trim(both '-' from regexp_replace(lower(trim(p_name)), '[^a-z0-9]+', '-', 'g')), 50);
  if v_base !~ '^[a-z0-9][a-z0-9-]{1,}$' then v_base := 'lab-' || substr(md5(p_name), 1, 6); end if;
  v_slug := v_base;
  while exists (select 1 from public.labs where slug = v_slug) loop
    n := n + 1; v_slug := v_base || '-' || n;
  end loop;
  insert into public.labs (slug, name, focus) values (v_slug, left(trim(p_name), 120), coalesce(p_focus, '{}')) returning * into v_row;
  return v_row;
end;
$$;

create or replace function public.assign_lab_head(p_lab uuid, p_user uuid)
returns void language plpgsql security definer set search_path = public as $$
declare v_name text; v_member uuid;
begin
  if not public.is_admin() then raise exception 'NOT_ALLOWED: only the coordinator assigns lab heads'; end if;
  if not exists (select 1 from public.labs where id = p_lab) then raise exception 'NOT_FOUND: lab'; end if;
  select coalesce(nullif(trim(first_name || ' ' || last_name), ''), email) into v_name from public.profiles where id = p_user;
  if v_name is null then raise exception 'NOT_FOUND: user'; end if;
  select id into v_member from public.lab_members where lab_id = p_lab and user_id = p_user;
  if v_member is not null then
    update public.lab_members set role = 'lead' where id = v_member;
  else
    insert into public.lab_members (lab_id, user_id, full_name, role, sort_order) values (p_lab, p_user, left(v_name, 120), 'lead', -1);
  end if;
end;
$$;

-- Removing a head keeps the person in the lab as a member.
create or replace function public.remove_lab_head(p_lab uuid, p_user uuid)
returns void language plpgsql security definer set search_path = public as $$
begin
  if not public.is_admin() then raise exception 'NOT_ALLOWED: only the coordinator removes lab heads'; end if;
  update public.lab_members set role = 'member' where lab_id = p_lab and user_id = p_user and public.is_lab_head_role(role::text);
  if not found then raise exception 'NOT_FOUND: this person is not a head of the lab'; end if;
end;
$$;

-- Lab Head requests are replaced by the coordinator's assignment.
create or replace function public.request_lab_head(p_lab uuid, p_position text default 'lead', p_note text default null)
returns public.lab_head_requests language plpgsql security definer set search_path = public as $$
begin
  raise exception 'NOT_ALLOWED: lab heads are assigned by the SITAM coordinator';
end;
$$;

/* ───────────── categories, projects, events ───────────── */
update public.labs set focus = array_replace(focus, 'Academic / Education', 'Courses') where 'Academic / Education' = any(focus);
update public.projects set kind = 'project' where kind::text = 'startup' and lab_id is not null;

create or replace function public.submit_project(
  p_kind text, p_title text, p_summary text, p_tags text[], p_authors text[], p_year int, p_status text,
  p_github_url text, p_demo_url text, p_paper_url text, p_contact_email text
) returns public.projects language plpgsql security definer set search_path = public as $$
begin
  raise exception 'NOT_ALLOWED: projects are added by lab heads on their lab page';
end;
$$;

-- Events belong to labs and are managed by their heads (and the coordinator).
create or replace function public.can_manage_event(p_event uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select public.is_admin()
      or exists (select 1 from public.event_hosts h where h.event_id = p_event and h.lab_id is not null and public.is_lab_manager(h.lab_id))
$$;

create or replace function public.save_event(
  p_id uuid, p_kind public.event_kind, p_title text, p_description text, p_starts_at timestamptz, p_room text,
  p_speaker text, p_speaker_role text, p_capacity int, p_lab_ids uuid[], p_company_ids uuid[], p_project_ids uuid[]
) returns uuid language plpgsql security definer set search_path = public as $$
declare v_id uuid; x uuid;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if not public.is_admin() then
    if coalesce(cardinality(p_lab_ids), 0) = 0 then raise exception 'NO_HOST: choose the lab that runs the event'; end if;
    if coalesce(cardinality(p_company_ids), 0) + coalesce(cardinality(p_project_ids), 0) > 0 then
      raise exception 'NOT_ALLOWED: events are hosted by labs';
    end if;
  end if;
  foreach x in array coalesce(p_lab_ids, '{}') loop
    if not public.is_lab_manager(x) then raise exception 'NOT_ALLOWED: only heads of the lab can publish its events'; end if;
  end loop;

  if p_id is null then
    insert into public.events (kind, title, description, starts_at, room, speaker, speaker_role, capacity, organizer_id)
    values (p_kind, trim(p_title), coalesce(p_description, ''), p_starts_at, coalesce(nullif(trim(p_room), ''), 'C1.2'), p_speaker, p_speaker_role, coalesce(p_capacity, 60), auth.uid())
    returning id into v_id;
  else
    if not public.can_manage_event(p_id) then raise exception 'NOT_ALLOWED: only heads of the hosting lab can edit this event'; end if;
    update public.events set kind = p_kind, title = trim(p_title), description = coalesce(p_description, ''), starts_at = p_starts_at,
      room = coalesce(nullif(trim(p_room), ''), 'C1.2'), speaker = p_speaker, speaker_role = p_speaker_role, capacity = coalesce(p_capacity, 60)
    where id = p_id;
    delete from public.event_hosts where event_id = p_id;
    v_id := p_id;
  end if;
  insert into public.event_hosts (event_id, lab_id) select v_id, unnest(coalesce(p_lab_ids, '{}'));
  insert into public.event_hosts (event_id, company_id) select v_id, unnest(coalesce(p_company_ids, '{}'));
  insert into public.event_hosts (event_id, project_id) select v_id, unnest(coalesce(p_project_ids, '{}'));
  return v_id;
end;
$$;

/* ───────────── my_context: + coordinator ───────────── */
create or replace function public.my_context()
returns jsonb language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'profile', (select to_jsonb(p) from public.profiles p where p.id = auth.uid()),
    'is_staff', public.is_staff(),
    'is_admin', public.is_admin(),
    'is_coordinator', public.is_coordinator(),
    'managed_labs', coalesce((
      select jsonb_agg(jsonb_build_object('id', l.id, 'slug', l.slug, 'name', l.name, 'role', m.role) order by l.name)
      from public.lab_members m join public.labs l on l.id = m.lab_id
      where m.user_id = auth.uid() and m.can_edit), '[]'::jsonb),
    'lab_memberships', coalesce((
      select jsonb_agg(jsonb_build_object('id', l.id, 'slug', l.slug, 'name', l.name, 'role', m.role, 'title', m.title,
                                          'can_edit', m.can_edit, 'is_head', public.is_lab_head_role(m.role::text)) order by l.name)
      from public.lab_members m join public.labs l on l.id = m.lab_id
      where m.user_id = auth.uid() and m.role::text <> 'former_lead'), '[]'::jsonb),
    'lab_head_requests', '[]'::jsonb,
    'companies', coalesce((
      select jsonb_agg(jsonb_build_object('id', c.id, 'name', c.name, 'verified', c.verified) order by c.name)
      from public.company_members cm join public.companies c on c.id = cm.company_id
      where cm.user_id = auth.uid()), '[]'::jsonb),
    'professor', (select jsonb_build_object('username', username, 'full_name', full_name) from public.professors where profile_id = auth.uid() limit 1),
    'saved_labs', coalesce((select jsonb_agg(lab_id) from public.saved_labs where user_id = auth.uid()), '[]'::jsonb),
    'pending_moderation', 0,
    'pending_lab_heads', 0
  )
$$;

do $$
declare f text;
begin
  foreach f in array array[
    'admin_create_lab(text, text[])', 'assign_lab_head(uuid, uuid)', 'remove_lab_head(uuid, uuid)',
    'add_lab_member(uuid, text, text, text, text)', 'my_context()', 'is_coordinator()'
  ] loop
    execute format('revoke execute on function public.%s from anon, public', f);
    execute format('grant execute on function public.%s to authenticated', f);
  end loop;
end $$;

