-- ════════ 20261103140000_sitam_v27_startup_people ════════
/* ════════════════════════════════════════════════════════════════════════════
   SITAM SPACE v27 — Startups: Mentors and Trackers tabs (requested 2026-11-03)
   • public.startup_people: people who help student startups — mentors (advice from experience) and trackers
     (guide a team step by step through the stages). Everyone can see them; only the coordinator / admin
     adds, edits and removes them (Startups → Mentors / Trackers → "Add …").
   Safe to run more than once.
   ════════════════════════════════════════════════════════════════════════════ */
create table if not exists public.startup_people (
  id uuid primary key default gen_random_uuid(),
  kind text not null check (kind in ('mentor', 'tracker')),
  full_name text not null check (char_length(btrim(full_name)) between 2 and 120),
  role text check (role is null or char_length(role) <= 160),
  bio text check (bio is null or char_length(bio) <= 1500),
  expertise text[] not null default '{}' check (cardinality(expertise) <= 12),
  photo_url text check (photo_url is null or photo_url ~* '^https://'),
  contact_url text check (contact_url is null or contact_url ~* '^(https://|mailto:)'),
  sort_order int not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists startup_people_kind_idx on public.startup_people (kind, sort_order, full_name);
alter table public.startup_people enable row level security;
drop policy if exists "Startup people: everyone reads" on public.startup_people;
drop policy if exists "Startup people: coordinator adds" on public.startup_people;
drop policy if exists "Startup people: coordinator edits" on public.startup_people;
drop policy if exists "Startup people: coordinator removes" on public.startup_people;
create policy "Startup people: everyone reads" on public.startup_people for select to anon, authenticated using (true);
create policy "Startup people: coordinator adds" on public.startup_people for insert to authenticated with check (public.is_admin());
create policy "Startup people: coordinator edits" on public.startup_people for update to authenticated using (public.is_admin()) with check (public.is_admin());
create policy "Startup people: coordinator removes" on public.startup_people for delete to authenticated using (public.is_admin());
revoke all on public.startup_people from anon, public;
grant select on public.startup_people to anon, authenticated;
grant insert, update, delete on public.startup_people to authenticated;

insert into sitam_meta.applied_migrations (version, name) values ('20261103140000', 'sitam_v27_startup_people') on conflict do nothing;

-- ════════ 20261103150000_sitam_v28_startup_details ════════
/* ════════════════════════════════════════════════════════════════════════════
   SITAM SPACE v28 — Startups: project card with details (requested 2026-11-03)
   • projects.logo_url: the startup's logo or photo (uploaded by the author to their own folder in "avatars").
   • project_startup_people: mentors / trackers (v27) who work with a startup, chosen when the project is proposed.
   • submit_startup(…, p_github_url, p_logo_url, p_people): new version without technologies; the old one stays
     for older pages. Safe to run more than once.
   ════════════════════════════════════════════════════════════════════════════ */
alter table public.projects add column if not exists logo_url text;
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'projects_logo_url_https') then
    alter table public.projects add constraint projects_logo_url_https check (logo_url is null or logo_url ~* '^https://');
  end if;
end $$;

create table if not exists public.project_startup_people (
  project_id uuid not null references public.projects(id) on delete cascade,
  person_id uuid not null references public.startup_people(id) on delete cascade,
  primary key (project_id, person_id)
);
create index if not exists project_startup_people_person_idx on public.project_startup_people (person_id);
alter table public.project_startup_people enable row level security;
drop policy if exists "Startup mentors: visible with the project" on public.project_startup_people;
-- visible when the project itself is visible to the reader (projects keeps its own rules)
create policy "Startup mentors: visible with the project" on public.project_startup_people for select to anon, authenticated
  using (exists (select 1 from public.projects p where p.id = project_id));
revoke all on public.project_startup_people from anon, authenticated, public;
grant select on public.project_startup_people to anon, authenticated;

create or replace function public.submit_startup(p_title text, p_summary text, p_demo_url text, p_stage text,
  p_github_url text, p_logo_url text, p_people uuid[])
returns public.projects language plpgsql security definer set search_path = public as $$
declare v_role text := public.my_role_text(); v_row public.projects; v_name text;
        v_url text := nullif(btrim(coalesce(p_demo_url, '')), '');
        v_git text := nullif(btrim(coalesce(p_github_url, '')), '');
        v_logo text := nullif(btrim(coalesce(p_logo_url, '')), '');
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED: sign in first'; end if;
  if v_role is null or v_role in ('partner', 'alumni') then raise exception 'NOT_ALLOWED: SDU accounts only'; end if;
  if char_length(btrim(coalesce(p_title, ''))) not between 2 and 120 then raise exception 'INVALID: the project name is required'; end if;
  if char_length(btrim(coalesce(p_summary, ''))) not between 20 and 1000 then raise exception 'INVALID: describe the idea and the solution (20+ characters)'; end if;
  if p_stage not in ('idea', 'prototype', 'mvp') then raise exception 'INVALID: choose the stage'; end if;
  if v_url is not null and v_url !~* '^https://' then raise exception 'INVALID: the link must start with https://'; end if;
  if v_git is not null and v_git !~* '^https://(www\.)?github\.com/' then raise exception 'INVALID: the GitHub link must start with https://github.com/'; end if;
  if v_logo is not null and v_logo !~* '^https://' then raise exception 'INVALID: upload the logo again'; end if;
  if cardinality(coalesce(p_people, '{}')) > 10 then raise exception 'INVALID: choose up to 10 mentors and trackers'; end if;
  if (select count(*) from public.projects where owner_id = auth.uid() and moderation = 'pending') >= 5 then
    raise exception 'TOO_MANY: wait until your pending submissions are reviewed';
  end if;
  select nullif(btrim(concat_ws(' ', first_name, last_name)), '') into v_name from public.profiles where id = auth.uid();
  insert into public.projects (lab_id, owner_id, kind, status, title, summary, tags, authors, year, demo_url, github_url, logo_url, stage, moderation, submitted_at)
  values (null, auth.uid(), 'startup', 'ongoing', btrim(p_title), btrim(p_summary), '{}',
          case when v_name is null then '{}' else array[v_name] end, extract(year from now())::int, v_url, v_git, v_logo, p_stage,
          case when public.is_admin() then 'approved' else 'pending' end, now())
  returning * into v_row;
  insert into public.project_startup_people (project_id, person_id)
  select v_row.id, sp.id from public.startup_people sp where sp.id = any(coalesce(p_people, '{}'))
  on conflict do nothing;
  return v_row;
end;
$$;
revoke execute on function public.submit_startup(text, text, text, text, text, text, uuid[]) from anon, public;
grant execute on function public.submit_startup(text, text, text, text, text, text, uuid[]) to authenticated;

insert into sitam_meta.applied_migrations (version, name) values ('20261103150000', 'sitam_v28_startup_details') on conflict do nothing;

-- ════════ 20261104100000_sitam_v29_centers_leads_passport ════════
/* ════════════════════════════════════════════════════════════════════════════
   SITAM SPACE v29 — Center of Research, lab leads 2026 with their own accounts, Lab Passport (approved by the user 2026-11-04)
   1. labs.center: 'ai' (Center of AI Research), 'math' (Center of Mathematics) or empty. For now no lab is in a center
      (the user, 2026-11-04). Only the coordinator puts a lab into a center (trigger labs_center_guard).
   2. Lab leads 2026 (list from the user, e-mails from the SITAM staff list): each one is the Head of their labs.
      Accounts that do not exist yet are created with the first password SduLab2026! and must change it at the first
      sign-in (profiles.must_change_password). Existing accounts keep their password and are only linked to the lab.
   3. lab_passports: the official Lab Passport (Зертхана паспорты) of a lab for a year. Heads of the lab and the
      coordinator read and fill it; it is submitted to the dean office and approved by the coordinator.
   Written without temp tables, semicolons inside texts or doubled quotes (the Supabase SQL editor). Safe to run more than once.
   ════════════════════════════════════════════════════════════════════════════ */

/* ───────────── 1. centers ───────────── */
alter table public.labs add column if not exists center text;
alter table public.labs drop constraint if exists labs_center_check;
alter table public.labs add constraint labs_center_check check (center is null or center in ('ai', 'math'));

create or replace function public.labs_center_guard()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.center is distinct from old.center and auth.uid() is not null and not public.is_admin() then
    raise exception 'NOT_ALLOWED: only the SITAM coordinator moves a lab to another center';
  end if;
  return new;
end;
$$;
drop trigger if exists labs_center_guard on public.labs;
create trigger labs_center_guard before update of center on public.labs for each row execute function public.labs_center_guard();


/* ───────────── 2. lab leads 2026 ───────────── */
alter table public.profiles add column if not exists must_change_password boolean not null default false;

create or replace function public.clear_must_change_password()
returns void language sql security definer set search_path = public as $$
  update public.profiles set must_change_password = false where id = auth.uid()
$$;
revoke execute on function public.clear_must_change_password() from anon, public;
grant execute on function public.clear_must_change_password() to authenticated;

create table if not exists sitam_meta.lab_leads_2026 (
  slug text not null, full_name text not null, email text not null, first_name text not null, last_name text not null, ord int not null, name_like text,
  primary key (slug, email)
);
alter table sitam_meta.lab_leads_2026 add column if not exists name_like text;
insert into sitam_meta.lab_leads_2026 (slug, full_name, email, first_name, last_name, ord, name_like) values
